from openpyxl import load_workbook

# Load the workbook and select the sheet
wb = load_workbook("input.xlsx")
sheet = wb["Sheet2"]

# Create a dictionary to store the weeks for each employee
employee_weeks = {}

# Iterate through the rows and collect data
for row in sheet.iter_rows(min_row=2, max_row=92, values_only=True):
    date, emp_num, abs_name, atts_name, week = row
    if emp_num not in employee_weeks:
        employee_weeks[emp_num] = []

    # Check for "Sick Day" and "Overtime" in the same week
    has_sick = abs_name == "Sick Day"
    has_overtime = atts_name == "Overtime"

    if has_sick or has_overtime:
        employee_weeks[emp_num].append((week, has_sick, has_overtime))

# Process the data to find weeks with both "Sick Day" and "Overtime"
result = []
for emp_num, weeks in employee_weeks.items():
    prev_week = None
    for week, has_sick, has_overtime in weeks:
        if prev_week is not None and prev_week != week:
            if has_sick and has_overtime:
                result.append("y")
            else:
                result.append("")
        else:
            result.append("")
        prev_week = week

# Write the result to the output range
for i, value in enumerate(result, start=2):
    sheet[f"F{i}"] = value

# Save the workbook as output.xlsx
wb.save("output.xlsx")
