from openpyxl import load_workbook

# Load the workbook and select the active sheet
wb = load_workbook("input.xlsx")
ws = wb.active

# Define ranges
month_names = [ws[f"B{row}"].value for row in range(3, 15)]  # B3:B14
month_end_dates = [ws[f"B{row}"].value for row in range(17, 25)]  # B17:B24
data_range = ws["C3:G24"]  # Data values to sum

# Map month names to their corresponding cells in C3:G14
result_cells = {}
for col in range(3, 8):  # Columns C to G
    for row in range(3, 15):  # Rows 3 to 14
        month_name = ws[f"B{row}"].value
        if month_name in month_names:
            result_cells[(month_name, col - 2)] = ws.cell(row=row, column=col)

# Create a dictionary to map month end dates to their data values
date_to_data = {}
for row in data_range:
    for cell in row:
        if cell.column == 2:  # Skip the first column (DATE)
            continue
        date_cell = ws.cell(row=cell.row, column=2)
        date = date_cell.value
        if date in month_end_dates:
            month = ws[f"B{date_cell.row - 14}"].value  # Map date to corresponding month name
            if month not in date_to_data:
                date_to_data[month] = {}
            date_to_data[month][cell.column - 2] = date_to_data[month].get(cell.column - 2, 0) + cell.value

# Fill the result cells with computed values
for month, data in date_to_data.items():
    for col, value in data.items():
        result_cells[(month, col)].value = value

# Save the workbook
wb.save("output.xlsx")
