from openpyxl import load_workbook
from openpyxl.utils import get_column_letter
import datetime

# Load the workbook and select the sheet
wb = load_workbook("input.xlsx")
ws = wb["Sheet1"]

# Read Group A data
group_a_data = {}
for row in ws.iter_rows(min_row=3, max_row=339, min_col=2, max_col=20):
    date_str = row[0].value
    if date_str is None:
        continue
    date = datetime.datetime.strptime(date_str, "%Y-%m")
    group_a_data[date] = [cell.value for cell in row[1:]]

# Read Group B dates
group_b_dates = []
for row in ws.iter_rows(min_row=19, max_row=339, min_col=1, max_col=1):
    date_str = row[0].value
    if date_str is None:
        continue
    try:
        date = datetime.datetime.strptime(date_str, "%Y-%m-%d %H:%M:%S")
        group_b_dates.append(date)
    except ValueError:
        continue

# Prepare Group B data
group_b_data = {date: [] for date in group_b_dates}

# Populate Group B data
for group_a_date, values in group_a_data.items():
    for i, value in enumerate(values):
        if value in (-9999, "M"):
            continue
        if value is None:
            group_b_data[group_b_dates[i]].append("NA")
        elif value == 0:
            group_b_data[group_b_dates[i]].append(0)
        else:
            group_b_data[group_b_dates[i]].append(value)

# Write Group B data to the output range
for i, date in enumerate(group_b_dates):
    if i + 19 > 339:
        break
    ws[f"B{i + 20}"] = group_b_data[date][0] if group_b_data[date] else ""

# Save the workbook
wb.save("output.xlsx")
